SELECT 
FROM ACCOUNT A LEFT JOIN CUSTOMER C ON C.CUSTOMER_ID = A.CUSTOMER_ID
WHERE A.ACCOUNT_ID = #{accountId}

SELECT 
FROM ACCOUNT A JOIN CUSTOMER C ON C.CUSTOMER_ID = A.CUSTOMER_ID
WHERE A.CUSTOMER_ID = #{customerId}

SELECT 
FROM ACCOUNT A LEFT JOIN CUSTOMER C ON C.CUSTOMER_ID = A.CUSTOMER_ID

  AND A.STATUS = #{status}
  AND A.ROLE = #{role}

ORDER BY A.CREATED_AT DESC, A.ACCOUNT_ID
FETCH FIRST #{limit} ROWS ONLY

mapper.update:
UPDATE ACCOUNT
SET FAILED_LOGIN_COUNT = FAILED_LOGIN_COUNT + 1,
    STATUS = CASE WHEN STATUS = 'ACTIVE' AND FAILED_LOGIN_COUNT + 1 >= #{lockThreshold}
                  THEN 'LOCKED' ELSE STATUS END
WHERE ACCOUNT_ID = #{accountId}
